import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Week 3 — Prompting & Save Points","description":"","frontmatter":{"source":"weeks/03-prompting-and-save-points/README.md"},"headers":[],"relativePath":"weeks/03-prompting-and-save-points/index.md","filePath":"weeks/03-prompting-and-save-points/index.md"}'),s={name:"weeks/03-prompting-and-save-points/index.md"};function i(n,e,h,d,l,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="week-3--prompting--save-points" tabindex="-1">Week 3 — Prompting &amp; Save Points <a class="header-anchor" href="#week-3--prompting--save-points" aria-label="Permalink to &quot;Week 3 — Prompting &amp; Save Points&quot;">​</a></h1><blockquote><p>A clear prompt tells the AI where to go; a commit makes sure you can always get back.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (≤30 min)</td><td>Your home page is live with a <strong>Projects</strong> section · you can sign in to a chat assistant with a live preview · read this page and the six steps of the <a href="./../../resources/safe-loop.html">Safe Loop</a> · skim the <a href="./game-menu.html">game menu</a> and pick two games</td></tr><tr><td><strong>Studio A</strong></td><td>Concept talk on prompts and git, then your first save points in github.dev: a four-part prompt, a diff, a commit with an <code>Assisted-by:</code> line, your History. Exit ticket (🔴 AI off)</td></tr><tr><td><strong>Studio B</strong></td><td><strong>Game in an Hour</strong>: a timed build of a small browser game, one commit per working step, then a two-minute play-test swap</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before)</td><td>Your game at <code>https://[your-username].github.io/game/</code>, finished, play-tested and linked from your home page · <code>PROMPTS.md</code> week 3 entries · on Canvas (the course&#39;s learning management system): your reflection. Full list: <a href="./homework.html#deliverables-checklist">deliverables checklist</a></td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: the practice change, the game, the giant-prompt experiment · 🟡 AI limited: none · 🔴 AI off: the link text, your diff readings, &quot;What I wrote or decided myself&quot;, the exit ticket and the reflection</td></tr><tr><td><strong>Must read</strong></td><td>This page, the <a href="./lab.html">lab</a>, the <a href="./homework.html">homework</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./game-menu.html">Game menu</a> · <a href="./../../resources/git-cheatsheet.html">Git Cheat Sheet</a> · <a href="./../../resources/prompt-patterns.html">Prompt Patterns</a> · <a href="./../../resources/troubleshooting.html">Troubleshooting</a> · <a href="./../../resources/glossary.html">Glossary</a> · <a href="./../../TOOLS.html">Tool Handout</a> · <a href="./../../resources/accessibility.html">Screen reader and keyboard guide</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Your game is at <code>/game/</code> with at least three working-step commits. Week 4 breaks it on purpose and restores it, so it needs those save points</td></tr><tr><td><strong>Time</strong></td><td>Studios 2 × 75 min · outside about 6 h (prep up to 30 min, homework core about 3 h, project time about 2 h, <code>PROMPTS.md</code> and reflection about 30 min); stretch is optional</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Write a prompt in four parts, <strong>Goal · Context · Constraints · Done when</strong>, and say why each part is there.</li><li>Decide what to paste into a prompt, knowing the AI sees only its context.</li><li>Ask for a plan before any code, and improve it.</li><li>Build in small steps, and explain why one giant prompt produces code that is hard to change.</li><li>Use the <strong>two-strikes rule</strong> when a fix isn&#39;t working.</li><li>In github.dev, commit with clear messages, read a diff, and find a file&#39;s history and a commit&#39;s hash.</li><li>Explain what <code>git revert</code> does and why it keeps the history.</li><li>Mark AI-helped commits with an <code>Assisted-by:</code> line.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Your home page is live at <code>https://[your-username].github.io</code>, with a <strong>Projects</strong> section that links to <code>game/</code>. If not, finish <a href="./../02-ship-your-page/">week 2</a> first, or ask for help.</li><li>☐ You can sign in to a chat assistant with a live preview (Gemini Canvas, or Claude Artifacts if you&#39;re 18+). Next week you need a <strong>second</strong> one from the <a href="./../../TOOLS.html">Tool Handout</a>.</li><li>☐ Read the six steps of the <a href="./../../resources/safe-loop.html">Safe Loop</a> (10 minutes; the rest of the page is for later).</li><li>☐ Skim the <a href="./game-menu.html">game menu</a> and pick two games. New to JavaScript or the web? Pick a ★ Easy game.</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap · concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-03.html" target="_blank" rel="noreferrer">slides</a>): prompts, context, small steps, two strikes, git, <code>Assisted-by:</code> · live demo · lab: create your game file, one change as one save point, read your History · checkpoint share · exit ticket (🔴 AI off)</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Ready check · <strong>Game in an Hour</strong> (60 minutes, timed) · play-test swap and checkpoint share. The game fills this studio, so the exit ticket comes at the end of Studio A</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="./lab.html">Lab</a></td><td>Step-by-step, both studios (must read)</td></tr><tr><td><a href="./homework.html">Homework</a></td><td>Core and stretch, with the deliverables checklist (must read)</td></tr><tr><td><a href="./game-menu.html">Game menu</a></td><td>Ten games with difficulty ratings and sample 5-step plans</td></tr><tr><td><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-03.html" target="_blank" rel="noreferrer">Slides</a></td><td>Studio A&#39;s concept talk</td></tr></tbody></table><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>If you are working through this week on your own, read this section, then do the <a href="./lab.html">lab</a>. The <a href="./../../resources/self-paced.html">self-paced path</a> says what to do instead of the pair activities.</p><h3 id="a-prompt-is-a-set-of-directions" tabindex="-1">A prompt is a set of directions <a class="header-anchor" href="#a-prompt-is-a-set-of-directions" aria-label="Permalink to &quot;A prompt is a set of directions&quot;">​</a></h3><p>A prompt is a work order for someone who can&#39;t ask you questions (unless you invite it to: the first of the three habits). Write it in four parts:</p><table tabindex="0"><thead><tr><th>Part</th><th>Question it answers</th><th>Example</th></tr></thead><tbody><tr><td><strong>Goal</strong></td><td>What do I want?</td><td>Make the snake speed up as it grows.</td></tr><tr><td><strong>Context</strong></td><td>What does the AI need to know?</td><td>Here is my current <code>game/index.html</code>: …</td></tr><tr><td><strong>Constraints</strong></td><td>What are the rules?</td><td>Change only the speed. Give me the complete file.</td></tr><tr><td><strong>Done when</strong></td><td>How will we both check?</td><td>After every 5 foods, the snake is visibly faster.</td></tr></tbody></table><p>&quot;Done when&quot; is the part people skip, and the most useful one: it turns &quot;looks fine&quot; into something you can test, like a program&#39;s expected output.</p><h3 id="the-ai-only-knows-whats-in-its-context" tabindex="-1">The AI only knows what&#39;s in its context <a class="header-anchor" href="#the-ai-only-knows-whats-in-its-context" aria-label="Permalink to &quot;The AI only knows what&#39;s in its context&quot;">​</a></h3><p>The model can&#39;t see your screen, your files or your repository, and a new chat starts empty. So paste what it needs: the current file, the exact error message, what you expected and what happened.</p><h3 id="small-steps-and-two-strikes" tabindex="-1">Small steps, and two strikes <a class="header-anchor" href="#small-steps-and-two-strikes" aria-label="Permalink to &quot;Small steps, and two strikes&quot;">​</a></h3><p>In a study of 33 learners using an AI code generator, those who generated a whole solution from one prompt did best on the first try, and worst when they later had to change their code (<a href="https://arxiv.org/abs/2309.14049" target="_blank" rel="noreferrer">Kazemitabaar et al., Koli Calling 2023</a>). Code always needs changing later, so build it in steps you can test and understand: <strong>ask for a plan first, edit it, then build one step at a time.</strong> The homework lets you try both on your own game. And when two attempts to fix the same problem fail, use <strong>the two-strikes rule</strong>: stop, go back to your last working version, and start a fresh chat with a better prompt.</p><h3 id="commits-are-save-points" tabindex="-1">Commits are save points <a class="header-anchor" href="#commits-are-save-points" aria-label="Permalink to &quot;Commits are save points&quot;">​</a></h3><p><strong><a href="./../../resources/glossary.html#git">Git</a></strong> tracks every version of your <strong><a href="./../../resources/glossary.html#repository">repository</a></strong> (a project folder), and GitHub stores it online. A <strong><a href="./../../resources/glossary.html#commit">commit</a></strong> is a save point with a message and a <strong><a href="./../../resources/glossary.html#commit-hash">hash</a></strong> (an ID like <code>4f2a9c1</code>); the <strong>history</strong> lists them all. A <strong><a href="./../../resources/glossary.html#diff">diff</a></strong> shows what changed: removed lines in red, added in green.</p><p>To undo a bad change, you don&#39;t delete it: you make a new commit that puts the file back, so the history keeps both the mistake and the fix. That&#39;s what <code>git revert</code> does (<a href="./../../resources/glossary.html#revert">revert</a>). You&#39;ll restore your game by hand next week, and type the real command in week 8.</p><p>This week you commit in <strong><a href="./../../resources/glossary.html#githubdev">github.dev</a></strong>: press <strong>.</strong> (period) on your repository page and VS Code opens in your browser. It edits and commits, but can&#39;t run programs.</p><h3 id="saying-when-ai-helped-the-assisted-by-line" tabindex="-1">Saying when AI helped: the <code>Assisted-by:</code> line <a class="header-anchor" href="#saying-when-ai-helped-the-assisted-by-line" aria-label="Permalink to &quot;Saying when AI helped: the `Assisted-by:` line&quot;">​</a></h3><p>Open-source projects such as LLVM and Fedora ask for a line like <code>Assisted-by: Gemini</code> at the end of a commit message when an AI tool helped (<a href="https://allthingsopen.org/articles/open-source-ai-contributions-assisted-by-git-trailer-standard" target="_blank" rel="noreferrer">All Things Open</a>). It tells readers which changes to check most carefully. Practice it from now; it&#39;s required from week 11.</p><h3 id="game-in-an-hour-is-graded-on-effort" tabindex="-1">Game in an Hour is graded on effort <a class="header-anchor" href="#game-in-an-hour-is-graded-on-effort" aria-label="Permalink to &quot;Game in an Hour is graded on effort&quot;">​</a></h3><p>The timer is real, but Game in an Hour is graded on effort, like every studio (<a href="./../../assessment/rubrics.html#labs">rubric</a>): a game that stops at step 3 with clean save points is a full-credit hour. Anyone may do it untimed (<a href="./../../resources/accessibility.html#timed-builds">Timed builds</a>).</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><ul><li><strong>At the end of Studio A:</strong> the Week 3 exit ticket (🔴 AI off, scored for completion). Expect: rewrite a weak prompt in four parts; what a diff shows; how to get back to an earlier version, and what happens to the bad commit; one question about your week 1 page.</li><li><strong>In Studio B:</strong> the play-test. Someone plays your game for two minutes without help, and you watch where they get stuck.</li></ul><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>About 5 hours of core work plus the journal; details on the <a href="./homework.html">homework page</a>. <strong>Project time:</strong> finish the game, a commit for each working step. <strong>Homework:</strong> play-test and fix, link the game by hand, read three of your own diffs (🔴 AI off), the giant-prompt experiment, and Simon Willison&#39;s &quot;Not all AI-assisted programming is vibe coding&quot;. <strong>Journal:</strong> <code>PROMPTS.md</code>; the reflection on Canvas (🔴 AI off). <strong>Stretch:</strong> a ★★★ game, or the study behind &quot;small steps&quot;.</p><p>Graded on effort and completion of the core tier (<a href="./../../assessment/rubrics.html#assignments">rubric</a>).</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>Your main assistant is down or you hit a limit</td><td>Switch to a fallback from the <a href="./../../TOOLS.html">Tool Handout</a> and paste your current <code>game/index.html</code> from GitHub. See <a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a></td></tr><tr><td>No assistant has a live preview</td><td>Commit each step and test it on your live site a minute later</td></tr><tr><td>github.dev won&#39;t open</td><td>Edit and commit on github.com with the pencil icon (<strong>Add file → Create new file</strong> for new files)</td></tr><tr><td>GitHub is down</td><td>Build in the chat preview, save the code in a text file after each working step, and commit the steps later</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li><a href="./../../resources/prompt-patterns.html">Prompt Patterns</a>: more prompt structures, with examples.</li><li><a href="https://arxiv.org/abs/2309.14049" target="_blank" rel="noreferrer">Kazemitabaar et al. (Koli Calling 2023)</a>: the study behind &quot;small steps&quot;.</li><li><a href="https://git-scm.com/book/en/v2" target="_blank" rel="noreferrer">Pro Git</a>, chapters 1–2: the free book on git, for when you want the full picture.</li><li>The <a href="./../../resources/reading-list.html">Reading List</a>.</li></ul>',40)])])}const p=t(s,[["render",i]]);export{u as __pageData,p as default};
